292				os.Exit(1)
293			}
294			cond, created, err := mevwatch.RegisterSuppression(args[1], raw)
295			if err != nil {
296				fmt.Fprintf(os.Stderr, "suppressions register: %v\n", err)
297				os.Exit(1)
298			}
299			writeJSON(struct {
300				Created     bool                 `json:"created"`
301				Suppression mevwatch.Suppression `json:"suppression"`
302			}{Created: created, Suppression: cond})
303		default:
304			fmt.Fprintf(os.Stderr, "unknown suppressions subcommand %q\n", args[0])
305			usage()
306			os.Exit(2)
307		}
308	}
309	
310	func runDemo() {
311		swaps := []mevwatch.Swap{
312			{TxHash: "0xfront", Pool: "pool-1", Trader: "bot-a", In: 500, Out: 480, GasPrice: 90, Index: 0},
313			{TxHash: "0xvictim", Pool: "pool-1", Trader: "user-1", In: 200, Out: 188, GasPrice: 12, Index: 1},
314			{TxHash: "0xback", Pool: "pool-1", Trader: "bot-a", In: 480, Out: 505, GasPrice: 80, Index: 2},
315		}
316		findings := mevwatch.Detect(swaps, "0xvictim")
317		for _, finding := range mevwatch.Rank(findings) {
318			fmt.Printf("tx=%s kind=%s severity=%d evidence=%v\n", finding.TxHash, finding.Kind, finding.Severity, finding.Evidence)
319		}
320		fmt.Printf("swaps=%d findings=%d\n", len(swaps), len(findings))
321	}
