func TestEvaluateReviewsCounts(t *testing.T) {
	dir := t.TempDir()
	// Block A (height 10): sandwich on 0xv (builtin).
	mustReplay(t, dir, reviewBlockInput("0xa", 10))
	// Block B (height 11): displacement on 0xd (builtin, 50 > 10*2).
	mustReplay(t, dir, strings.Replace(reviewBlockInput("0xb", 11), `"0xa"`, `"0xb"`, 1))
	// Block C (height 12): displacement on 0xn, archived under noRules (no
	// original findings), candidate builtin flags it as pending.
	registerReviewVersion(t, dir, noRulesSpec)
	mustReplayWithVersion(t, dir, strings.Replace(reviewBlockInput("0xc", 12), `"0xa"`, `"0xc"`, 1), "noRules")
	// Block D (height 13): sandwich on 0xk (also displacement-capable).
	mustReplay(t, dir, strings.Replace(strings.Replace(reviewBlockInput("0xd", 13), `"0xa"`, `"0xd"`, 1), `"0xv"`, `"0xk"`, 1))
	// Block E (height 14): sandwich on 0xw, withdrawn after first review.
	mustReplay(t, dir, strings.Replace(strings.Replace(reviewBlockInput("0xe", 14), `"0xa"`, `"0xe"`, 1), `"0xv"`, `"0xw"`, 1))

	// Reviews.
	// A: RR sandwich → builtin still flags sandwich → kept.
	if _, err := SubmitReview(dir, reviewSpec("1", "0xa", "0xv", "sandwich", "c1", "a", "real", 0, ReviewRealRisk)); err != nil {
		t.Fatal(err)
	}
	// A: FP displacement → builtin still flags displacement → stillHit.
	if _, err := SubmitReview(dir, reviewSpec("1", "0xa", "0xd", "displacement", "c2", "a", "fp", 0, ReviewFalsePositive)); err != nil {
		t.Fatal(err)
	}
	// B: RR displacement → noDisplacement drops it → missed.
	registerReviewVersion(t, dir, noDisplacementSpec)
	if _, err := SubmitReview(dir, reviewSpec("1", "0xb", "0xd", "displacement", "c3", "a", "real", 0, ReviewRealRisk)); err != nil {
		t.Fatal(err)
	}
	// B: FP sandwich → builtin still flags sandwich → stillHit.
	if _, err := SubmitReview(dir, reviewSpec("1", "0xb", "0xv", "sandwich", "c4", "a", "fp", 0, ReviewFalsePositive)); err != nil {
		t.Fatal(err)
	}
	// D: RR sandwich → noSandwich drops sandwich, candidate flags displacement
	// instead → missed (sandwich) + pending (displacement).
	registerReviewVersion(t, dir, noSandwichSpec)
	if _, err := SubmitReview(dir, reviewSpec("1", "0xd", "0xk", "sandwich", "c5", "a", "real", 0, ReviewRealRisk)); err != nil {
		t.Fatal(err)
	}
	// E: RR sandwich then withdrawn → treated as unreviewed → pending.
	if _, err := SubmitReview(dir, reviewSpec("1", "0xe", "0xw", "sandwich", "c6", "a", "real", 0, ReviewRealRisk)); err != nil {
		t.Fatal(err)
	}
	if _, err := SubmitReview(dir, reviewSpec("1", "0xe", "0xw", "sandwich", "c7", "a", "withdrawn", 1, ReviewUnreviewed)); err != nil {
		t.Fatal(err)
	}

	got, err := EvaluateReviews(dir, "1", 0, 100, BuiltinVersionID)
	if err != nil {
		t.Fatal(err)
	}
	// With builtin as the candidate:
	//   A: kept (sandwich RR), stillHit (displacement FP)
	//   B: stillHit (sandwich FP); displacement RR is missed under noDisplacement
	//      but builtin still flags it → kept actually. Wait — B's displacement
	//      review is RR, candidate builtin still flags displacement → kept.
	//   C: pending (displacement, no original finding)
	//   D: sandwich RR, builtin still flags sandwich → kept; displacement pending
	//   E: withdrawn → pending
	// So: kept=3 (A sandwich, B displacement, D sandwich), missed=0,
	//     stillHit=2 (A displacement, B sandwich), eliminated=0,
	//     pending=3 (C displacement, D displacement, E sandwich).
	if got.Kept != 3 {
		t.Fatalf("kept = %d, want 3", got.Kept)
	}
	if got.Missed != 0 {
		t.Fatalf("missed = %d, want 0", got.Missed)
	}
	if got.StillHit != 2 {
		t.Fatalf("stillHit = %d, want 2", got.StillHit)
	}
	if got.Eliminated != 0 {
		t.Fatalf("eliminated = %d, want 0", got.Eliminated)
	}
	if got.PendingReview != 3 {
		t.Fatalf("pending = %d, want 3", got.PendingReview)
	}
}

